<tr><td>пиэль</td><td><span class="he">לְ_ַ_ֵּ_</span> <span class="tr">лэ-а-э́-</span></td><td><span class="he">מְדַבֵּר</span></td><td><span class="he">לְדַבֵּר</span> <span class="tr">лэдабэ́р</span> — говорить</td></tr>
